{"implementation":"def solve(case):
    data = case.get("payload", case) if isinstance(case, dict) else case
    nodes = list(data["nodes"])
    core = data["core_distance"]

    weighted_edges = []
    mutual_reachability = []
    for index, edge in enumerate(data["distances"]):
        left, right, distance = edge
        weight = max(distance, core[left], core[right])
        mutual_reachability.append([left, right, weight])
        weighted_edges.append((weight, index, left, right))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        root = node
        while parent[root] != root:
            root = parent[root]
        while parent[node] != node:
            next_node = parent[node]
            parent[node] = root
            node = next_node
        return root

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return False
        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root
        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1
        return True

    mst = []
    for weight, index, left, right in sorted(weighted_edges):
        if union(left, right):
            mst.append([left, right, weight])
            if len(mst) == max(0, len(nodes) - 1):
                break

    return {"mutual_reachability": mutual_reachability, "mst": mst}
